export async function run(only?: string, onCase?: (a0: CaseResult) => void) {
  const results: CaseResult[] = [];
  const want = (n: string): boolean => only === undefined || only === n;
  if (want("a refund is forwarded")) {
    const started = __bynkCaseNow();
    const r = { name: "a refund is forwarded", ...(await test_a_refund_is_forwarded()), durationMs: __bynkCaseSince(started) };
    results.push(r);
    if (onCase) onCase(r);
  }
  if (want("a rejected message carries the handler's reason")) {
    const started = __bynkCaseNow();
    const r = { name: "a rejected message carries the handler's reason", ...(await test_a_rejected_message_carries_the_handler_s_reason()), durationMs: __bynkCaseSince(started) };
    results.push(r);
    if (onCase) onCase(r);
  }
  if (want("a message with no DMARC verdict is accepted without a reply")) {
    const started = __bynkCaseNow();
    const r = { name: "a message with no DMARC verdict is accepted without a reply", ...(await test_a_message_with_no_DMARC_verdict_is_accepted_without_a_reply()), durationMs: __bynkCaseSince(started) };
    results.push(r);
    if (onCase) onCase(r);
  }
  if (want("a message Cloudflare authenticated is answered")) {
    const started = __bynkCaseNow();
    const r = { name: "a message Cloudflare authenticated is answered", ...(await test_a_message_Cloudflare_authenticated_is_answered()), durationMs: __bynkCaseSince(started) };
    results.push(r);
    if (onCase) onCase(r);
  }
  return results;
}
